var vals = [5.264,5.286,5.361,5.354,5.328,5.363,5.348,5.296,5.327,5.296,5.303,5.402,5.462,5.502,5.562,5.594,5.639,5.603,5.63,5.664,5.641,5.683];
var n = vals.length;
