<script>
(function(){
var _cs = document.currentScript;
var NS = "http://www.w3.org/2000/svg";
var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
function el(tag, attrs, txt){ var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); if (txt !== undefined) e.textContent = txt; return e; }
function T(s, x, y, size, weight, fill, anchor){ return el("text", {x: x, y: y, "font-size": size, "font-weight": weight, fill: fill, "text-anchor": anchor, "font-family": FONT}, s); }
var svg = document.createElementNS(NS, "svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");
var labels = ["T1 23","T2 23","T3 23","T4 23","T1 24","T2 24","T3 24","T4 24","T1 25","T2 25","T3 25","T4 25","T1 26","T2 26","T3 26","T4 26"];
var vals = [4,5,5,5,6,6,5,5,4,4,3,3,3,3,3,3];
var n = vals.length;
var margin = {left: 62, right: 24, top: 18, bottom: 46};
var PW = 680 - margin.left - margin.right;
var PH = 300 - margin.top - margin.bottom;
var MT = margin.top;
var vmin = Math.min.apply(null, vals) - 0.5;
var vmax = Math.max.apply(null, vals) + 0.5;
function xp(i){ return margin.left + (i / (n - 1)) * PW; }
function yp(v){ return MT + ((vmax - v) / (vmax - vmin)) * PH; }
function tw(s, size, k){ return s.length * size * k; }
var evI = 4, bandA = 10, bandB = n - 1;
var refVal = 3.985;
var lastX = xp(n - 1), lastY = yp(vals[n - 1]);
var pillVal = vals[n - 1];
var gridTicks = [3, 4, 5, 6];
svg.appendChild(el("rect", {x: xp(bandA), y: MT, width: xp(bandB) - xp(bandA), height: PH, fill: "#2e7d32", opacity: 0.07}));
gridTicks.forEach(function(t){ svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(t), y2: yp(t), stroke: "#ececec", "stroke-width": 0.5})); });
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(refVal), y2: yp(refVal), stroke: "#2e7d32", "stroke-width": 1, "stroke-dasharray": "3,3"}));
var d = "";
vals.forEach(function(v, i){ if (i === 0) { d += "M" + xp(0).toFixed(1) + " " + yp(v).toFixed(1) + " "; } else { d += "L" + xp(i).toFixed(1) + " " + yp(vals[i - 1]).toFixed(1) + " L" + xp(i).toFixed(1) + " " + yp(v).toFixed(1) + " "; } });
svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 2, "stroke-linejoin": "round"}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: xp(evI), x2: xp(evI), y1: MT, y2: MT + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 4, fill: "#4a5568"}));
var pillText = pillVal + " %";
var pillW = Math.ceil(tw(pillText, 9, 0.58)) + 10;
var pillH = 16;
var pillX = lastX - pillW - 6;
if (pillX < margin.left) pillX = margin.left;
var pillY = lastY - pillH / 2;
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(T(pillText, pillX + pillW / 2, pillY + pillH / 2 + 4, 9, 700, "#111111", "middle"));
gridTicks.forEach(function(t){ if (t !== pillVal) svg.appendChild(T(t + " %", margin.left - 6, yp(t) + 3, 8.5, 400, "#aaaaaa", "end")); });
labels.forEach(function(s, i){ svg.appendChild(T(s, xp(i), MT + PH + 16, 8, 400, "#999999", "middle")); });
svg.appendChild(T("6 TRIMESTRES AU CREUX", (xp(bandA) + xp(bandB)) / 2, MT + 10, 7, 700, "#2e7d32", "middle"));
var evLines = ["T1 2024", "PIC"];
var evW = Math.max(tw(evLines[0], 7, 0.68), tw(evLines[1], 7, 0.68));
var exx = xp(evI);
var nearRight = (exx + evW + 3) > (margin.left + PW);
var evAnchor = nearRight ? "end" : "start";
var evOff = nearRight ? -3 : 3;
evLines.forEach(function(s, k){ svg.appendChild(T(s, exx + evOff, MT + 50 + k * 9, 7, 700, "#1a3560", evAnchor)); });
if (Math.abs(refVal - pillVal) / pillVal >= 0.03) {
  svg.appendChild(T("GC 10 ANS 3,99 % AU 7 OCT.", xp(bandA + 1), yp(refVal) - 10, 7, 700, "#2e7d32", "start"));
}
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Agence du revenu du Canada, taux d’intérêt prescrits, T1 2023 à T4 2026&nbsp;; Investment Executive, 28 août 2026&nbsp;; rendement des obligations du gouvernement du Canada à 10 ans au 7 octobre 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Le taux est établi chaque trimestre à partir du rendement moyen des bons du Trésor du gouvernement du Canada à trois mois au cours du premier mois du trimestre précédent, arrondi au point de pourcentage entier supérieur. La ligne pointillée indique le rendement à 10 ans de 3,985&nbsp;% le 7 octobre.</p>
<h2>D’où vient l’écart</h2>
<p>Un prêt hypothétique de 500&nbsp;000&nbsp;$ à 3&nbsp;% génère 15&nbsp;000&nbsp;$ d’intérêts annuels à la charge du conjoint emprunteur ou de la fiducie familiale. La même somme investie au rendement à 10 ans de 3,985&nbsp;% rapporte 19&nbsp;925&nbsp;$, soit un écart brut de 4&nbsp;925&nbsp;$ avant impôt. L’avantage de la structure tient à ce que le revenu de placement est imposé entre les mains de l’emprunteur au revenu plus faible, tandis que le prêteur déclare les 15&nbsp;000&nbsp;$ d’intérêts.</p>
<p>La structure s’applique aux comptes non enregistrés. Les cotisations au CELI n’exigent pas de prêt&nbsp;: le don d’une somme à un conjoint pour financer une cotisation au CELI n’est pas assujetti à l’attribution, et le plafond du CELI de 2026 est de 7&nbsp;000&nbsp;$. Le REER de conjoint est l’autre solution, le plafond du REER de 2026 s’établissant à 33&nbsp;810&nbsp;$ et la date limite de cotisation pour l’année d’imposition 2026 étant le 1er mars 2027.</p>
<h2>Les prêts existants consentis à 4&nbsp;%, 5&nbsp;% et 6&nbsp;%</h2>
<p>Les prêts consentis entre le premier trimestre de 2023 et le deuxième trimestre de 2025 ont fixé des taux de 4&nbsp;%, 5&nbsp;% ou 6&nbsp;%, et ces taux demeurent avec le prêt. Un emprunteur qui paie 6&nbsp;% sur un prêt consenti au début de 2024 paie le double du taux prescrit actuel. Certains praticiens remboursent un tel prêt et le remplacent par un nouveau prêt au taux actuel. Le remboursement doit être réel, et la séquence relève du fiscaliste du client.</p>
<p>Pour les clients constitués en société, le taux de 3&nbsp;% de l’avantage imposable sur les prêts à faible intérêt consentis aux employés et aux actionnaires correspond au taux prescrit du quatrième trimestre de 2026. Le taux d’intérêt sur les arriérés d’impôt se situe quatre points au-dessus du taux prescrit par formule, soit 7&nbsp;%, de sorte qu’un client qui a des acomptes provisionnels de 2026 impayés paie plus du double du taux des prêts familiaux sur ce solde.</p>',
'<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients qui ont des prêts à taux prescrit consentis à 4&nbsp;%, 5&nbsp;% ou 6&nbsp;% se sentent probablement coincés&nbsp;: ils paient un taux nettement supérieur aux 3&nbsp;% annoncés. Les clients qui ont entendu parler du fractionnement du revenu sans jamais agir peuvent avoir l’impression d’avoir raté la fenêtre, ou soupçonner une échéance qui n’existe pas.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Le taux que l’ARC applique aux prêts familiaux est de 3&nbsp;% ce trimestre, et d’après le rendement actuel des bons du Trésor à court terme, il devrait rester à 3&nbsp;% pour le premier trimestre de 2027. Rien ne nous force donc à une décision précipitée à cause d’une falaise du taux. Ce qui a bel et bien une date, c’est le paiement des intérêts sur tout prêt, exigible le 30 janvier, et notre planification de fin d’année. Laissez-moi examiner ce que vous avez en place, à quel taux cela a été fixé et si cela se justifie encore, puis nous déciderons ensemble quoi faire et dans quel ordre.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> Les couples dont l’écart de revenu est important et qui détiennent un portefeuille non enregistré substantiel, surtout ceux qui ont des prêts consentis entre 2023 et la mi-2025 à des taux de 4&nbsp;% à 6&nbsp;%.</p>
<p><strong>Incidence variable&nbsp;:</strong> Les clients qui ont des droits de cotisation inutilisés au CELI ou au REER, où les cotisations enregistrées peuvent être la première étape avant un prêt. Les clients constitués en société qui ont des prêts d’actionnaire, auxquels s’applique le taux d’avantage de 3&nbsp;%.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> Les clients qui envisagent un premier prêt à 3&nbsp;% avec un conjoint ou une fiducie familiale comme emprunteur.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Dresser la liste des clients qui ont un prêt à taux prescrit en cours, avec la date du prêt et le taux fixé.</div>
<div class="checklist-item">Confirmer que les intérêts des prêts de 2026 seront payés d’ici le 30 janvier 2027 et inscrire un rappel à l’agenda.</div>
<div class="checklist-item">Signaler les prêts à 4&nbsp;% ou plus pour une discussion sur le remboursement et le remplacement avec le fiscaliste du client.</div>
<div class="checklist-item">Vérifier les droits de cotisation inutilisés au CELI et au REER, et noter la date limite du 1er mars 2027 pour le REER.</div>
<div class="checklist-item">Inscrire à l’agenda l’annonce du taux prescrit du premier trimestre de 2027 par l’ARC, à la fin de novembre ou au début de décembre.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Votre prêt familial et le taux prescrit de 3&nbsp;%<br><br>
Bonjour [Nom du client],<br><br>
Merci pour la conversation d’aujourd’hui. Comme nous en avons discuté, le taux prescrit de l’ARC est de 3&nbsp;% pour le quatrième trimestre et les rendements des bons du Trésor à court terme laissent entrevoir 3&nbsp;% de nouveau pour le premier trimestre de 2027, de sorte qu’aucune échéance n’est dictée par le taux.<br><br>
Deux dates comptent&nbsp;: le 30 janvier 2027, date à laquelle les intérêts de 2026 sur tout prêt à taux prescrit doivent être payés, et le 1er mars 2027 pour les cotisations au REER de l’année d’imposition 2026. J’examinerai les modalités de votre prêt actuel en regard du taux de 3&nbsp;% et je vous enverrai un court résumé avant que nous parlions à votre fiscaliste.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
'<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Couples à revenu unique détenant des portefeuilles non enregistrés&nbsp;:</strong> l’écart de revenu entre les conjoints est la condition qui rend la structure utile.</p>
<p><strong>Propriétaires d’entreprise ayant des revenus de placement imposables&nbsp;:</strong> ils détiennent souvent à la fois des actifs de société et des actifs personnels et n’ont pas examiné la planification de prêts familiaux.</p>
<p><strong>Retraités dont les revenus de pension sont inégaux&nbsp;:</strong> le conjoint au revenu plus élevé paie peut-être de l’impôt sur des revenus de placement que l’autre pourrait déclarer à un taux plus bas.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Le taux des prêts familiaux de l’ARC est de 3&nbsp;% depuis six trimestres de suite, et à l’approche de la fin de l’année, je vous appelle pour savoir si vous l’avez déjà envisagé pour votre ménage.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Le taux de 3&nbsp;% est fixe pour toute la durée du prêt, et le rendement des obligations du gouvernement du Canada à 10 ans avoisine 4&nbsp;%. Cet écart ne garantit aucun résultat, mais c’est la condition dont la stratégie a besoin.</p>
<p>Un couple autonome a rarement quelqu’un pour suivre le paiement des intérêts du 30 janvier, les règles d’attribution ou le taux des prêts existants. Une conversation de planification regroupe tout cela dans un seul calendrier.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>1. L’un des conjoints déclare-t-il la majeure partie du revenu de placement du ménage&nbsp;?</p>
<p>2. Avez-vous déjà mis en place un prêt entre conjoints ou à une fiducie familiale, et à quel taux&nbsp;?</p>
<p>3. De combien de droits de cotisation inutilisés au CELI et au REER disposez-vous chacun&nbsp;?</p>
<p>4. Qui suit les échéances fiscales liées aux revenus de placement dans votre ménage&nbsp;?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Le taux de 3&nbsp;% des prêts familiaux et votre calendrier de fin d’année<br><br>
Bonjour [Nom],<br><br>
Le taux de l’ARC pour les prêts familiaux est de 3&nbsp;% depuis six trimestres d’affilée et semble devoir se maintenir au premier trimestre de 2027. Si l’un de vous déclare la plupart des revenus de placement du ménage, une courte conversation avant la fin de l’année pourrait valoir la peine.<br><br>
Seriez-vous ouvert à un appel de 15 minutes cette semaine&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
