function T(s, x, y, size, weight, fill, anchor){ return el("text", {x: x, y: y, "font-size": size, "font-weight": weight, fill: fill, "text-anchor": anchor, "font-family": FONT}, s); }
var svg = document.createElementNS(NS, "svg");
