function tw(s, size, k){ return s.length * size * k; }
var ma = [];
vals.forEach(function(v, i){ if (i >= 4) { var s = 0; for (var j = i - 4; j <= i; j++) { s += vals[j]; } ma.push({i: i, v: s / 5}); } });
var bandA = 12, bandB = n - 1;
var refs = [{v: 36513.80, label: "4 SEPT. : 36 514", color: "#2e7d32"}, {v: 35154.76, label: "CREUX 1ER OCT.", color: "#7a3030"}];
var events = [{i: 7, lines: ["16 SEPT.", "FED +25"]}, {i: 12, lines: ["30 ANS +9,9 PB", "TSX -1,6 %"]}];
